void handler(int sig) { /* Async-safe code only */ }

// Robust Signal Handler Setup (ECF Control)
struct sigaction sa;
sa.sa_handler = handler;
sigemptyset(&sa.sa_mask); // Set mask for signals blocked during execution
sa.sa_flags = SA_RESTART; 

sigaction(SIGINT, &sa, NULL); 

// Explicitly blocking signals using a syscall
sigset_t block_mask, prev_mask;
sigemptyset(&block_mask);
sigaddset(&block_mask, SIGUSR1);
sigprocmask(SIG_BLOCK, &block_mask, &prev_mask); 

// Core System Call (Process ECF)
pid_t pid = fork();
if (pid == 0) { /* Child */ }
else if (pid > 0) { wait(NULL); /* Parent */ }
// Restore original mask
sigprocmask(SIG_SETMASK, &prev_mask, NULL);
